  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '80947fa1-caaa-4c11-9a63-f20b363ae133', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$Why does Ausable seem to be disappointed at the beginning of their encounter?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Because he believes his methods are too traditional and boring"},{"id":"b","text":"Because he doesn't like the place where they have met"},{"id":"c","text":"Because he thinks Fowler is not a real secret agent as expected"},{"id":"d","text":"Because he didn't receive any messages from dark-eyed beauties"}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-29-170Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
