  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '80947fa1-caaa-4c11-9a63-f20b363ae133', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$How does Max's arrival reflect on Ausable as a character?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Ausable appears to be expecting someone who will challenge his position or intentions."},{"id":"b","text":"It shows that Ausable is always prepared and unflappable, regardless of the situation."},{"id":"c","text":"Max’s presence indicates Ausable is not a reliable source for information about the document's importance."},{"id":"d","text":"The unexpected arrival suggests that Max might be an antagonist in this story."}]$qbx$::jsonb, $qbx$a$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-29-170Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
