  ('ba4eb5b3-e9c0-48ec-8f93-153a4b623240', '8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '80947fa1-caaa-4c11-9a63-f20b363ae133', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$You have been bored!” The fat man chuckled to himself as he unlocked the door of his room and stood aside to let his frustrated guest enter.$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-29-170Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
